const b = $input.first().json;
const stockProviders = (b.providers && b.providers.stock_media) || [];
const provider = stockProviders.find((p) => p.enabled && p.provider === 'pexels') || stockProviders[0] || { provider: 'pexels', settings: {} };
const settings = provider.settings || {};
const isVideo = b.visual_type === 'stock_video';
const params = {
  query: b.search_query || '', orientation: settings.orientation || 'landscape', per_page: '5',
};
const qs = Object.keys(params).map((k) => encodeURIComponent(k) + '=' + encodeURIComponent(params[k])).join('&');
const url = (isVideo ? 'https://api.pexels.com/videos/search' : 'https://api.pexels.com/v1/search') + '?' + qs;
return [{ json: { ctx: b, isVideo, url } }];

const resp = $input.first().json;
const ctx = $('Prepare Search Request').first().json.ctx;
const statusCode = resp.statusCode || resp.status || 0;
const retryable = statusCode === 0 || statusCode === 429 || statusCode >= 500;
return [{ json: {
  success: false, data: null,
  error: { code: 'VISUAL_SOURCE_SEARCH_FAILED', message: 'Pexels search call failed (status ' + statusCode + ')', retryable, error_id: null },
  runtime: { channel_id: ctx.channel_id }
} }];

const resp = $input.first().json;
const { isVideo } = $('Prepare Search Request').first().json;
let candidates = [];
if (isVideo) {
  candidates = (resp.videos || []).map((v) => {
    const best = (v.video_files || []).slice().sort((a, b2) => (b2.width * b2.height) - (a.width * a.height))[0] || {};
    return {
      provider: 'pexels', provider_asset_id: 'pexels-video-' + v.id, type: 'video',
      source_page_url: v.url, download_url: best.link, width: best.width || v.width, height: best.height || v.height,
      duration_seconds: v.duration || null, creator: (v.user && v.user.name) || null,
      license: 'Pexels License', attribution_required: false, commercial_use_allowed: true,
    };
  });
} else {
  candidates = (resp.photos || []).map((p) => ({
    provider: 'pexels', provider_asset_id: 'pexels-photo-' + p.id, type: 'image',
    source_page_url: p.url, download_url: (p.src && (p.src.original || p.src.large2x || p.src.large)) || null,
    width: p.width, height: p.height, duration_seconds: null, creator: p.photographer || null,
    license: 'Pexels License', attribution_required: false, commercial_use_allowed: true,
  }));
}
return [{ json: { success: true, data: { candidates }, error: null, runtime: {} } }];
